<div class="auth-card mx-auto"><h1>Welcome back</h1><p class="text-muted">Sign in to continue sharing memories.</p><?php if(!empty($error)): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><?php if($lastLogin): ?><div class="alert alert-info"><i class="bi bi-clock"></i> Last login from this computer: <strong><?=e($lastLogin)?></strong></div><?php endif; ?><form method="post" action="<?=url('login')?>" class="needs-validation" autocomplete="off" novalidate><input type="hidden" name="csrf" value="<?=csrfToken()?>"><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" autocomplete="off" required value="<?=old('email')?>"><label class="form-label">Password</label><div class="input-group mb-3"><input id="loginPassword" class="form-control" type="password" name="password" autocomplete="new-password" required><button class="btn btn-outline-secondary toggle-password" type="button" data-target="loginPassword" aria-label="Show password"><i class="bi bi-eye"></i></button></div><button class="btn btn-dark w-100">Login</button></form><p class="mt-3 text-center">New here? <a href="<?=url('register')?>">Create an account</a></p></div>
